#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T = 1;
    for (int t = 0; t < T; t++) {
        int n, mod;
        cin >> n >> mod;
        vector<vector<long long>> dp(n, vector<long long>(n * n + 5, 0));
        dp[0][0] = 1;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < (int)dp[0].size(); j++) {
                for (int cnt = 0; cnt <= i; cnt++) {
                    if (j - cnt >= 0) {
                        dp[i][j] += dp[i - 1][j - cnt];
                        dp[i][j] %= mod;
                    }
                }
            }
        }
        vector<vector<long long>> sums(n, vector<long long>(dp[0].size(), 0));
        for (int i = 0; i < n; i++) {
            long long sum = 0;
            for (int j = 0; j < (int)dp[0].size(); j++) {
                sum += dp[i][j];
                sum %= mod;
                sums[i][j] = sum;
            }
        }
        vector<long long> fact(501 * 501, 1);
        for (int i = 2; i < (int)fact.size(); i++) {
            fact[i] = (fact[i - 1] * i) % mod;
        }
        vector<vector<long long>> ncr(501, vector<long long>(501, 0));
        ncr[0][0] = 1;
        for (int i = 1; i < 501; i++) {
            ncr[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                ncr[i][j] = (ncr[i - 1][j] + ncr[i - 1][j - 1]) % mod;
            }
        }
        long long res = 0;
        for (int i = n - 2; i >= 0; i--) {
            int cnt = n - i;
            int pre = n - cnt;
            long long com = (ncr[n][pre] * fact[pre]) % mod;
            long long sum = 0;
            for (int dif = 1; dif < cnt; dif++) {
                for (int inv = dif; inv < (int)dp[0].size(); inv++) {
                    if (dp[cnt - 1][inv] == 0) break;
                    if (inv - dif - 1 < 0) continue;
                    long long x = dp[cnt - 2][inv];
                    long long y = sums[cnt - 2][inv - dif - 1];
                    x = (x * y) % mod;
                    sum += (x * (cnt - dif)) % mod;
                    sum %= mod;
                }
            }
            res += (sum * com) % mod;
            res %= mod;
        }
        cout << res % mod << "\n";
    }
    return 0;
}

